import type { Metadata } from "next";
import { getTranslations } from "next-intl/server";

import { AuthCard } from "@/components/auth/auth-card";
import { ForgotPasswordForm } from "@/components/auth/forgot-password-form";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("auth-password-reset");
  return {
    title: t("forgotPage.metadata.title"),
    description: t("forgotPage.metadata.description"),
  };
}

export default async function ForgotPasswordPage() {
  const t = await getTranslations("auth-password-reset");

  return (
    <AuthCard
      title={t("forgotPage.card.title")}
      description={t("forgotPage.card.description")}
    >
      <ForgotPasswordForm />
    </AuthCard>
  );
}

import type { Metadata } from "next";
import { Suspense } from "react";
import { getTranslations } from "next-intl/server";

import { AuthCard } from "@/components/auth/auth-card";
import { ResetPasswordForm } from "@/components/auth/reset-password-form";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("auth-password-reset");
  return {
    title: t("resetPage.metadata.title"),
    description: t("resetPage.metadata.description"),
  };
}

export default async function ResetPasswordPage() {
  const t = await getTranslations("auth-password-reset");

  return (
    <AuthCard
      title={t("resetPage.card.title")}
      description={t("resetPage.card.description")}
    >
      {/* useSearchParams (inside ResetPasswordForm) requires a Suspense
          boundary — it opts the subtree out of full static rendering. */}
      <Suspense
        fallback={
          <div className="text-center text-sm text-muted-foreground">
            {t("resetPage.loading")}
          </div>
        }
      >
        <ResetPasswordForm />
      </Suspense>
    </AuthCard>
  );
}

"use client";

/**
 * Email-only form that starts the password reset flow. Calls the
 * Better-Auth client SDK's `requestPasswordReset` action directly — no
 * raw `fetch("/api/auth/*")`. `redirectTo` is where Better-Auth sends the
 * visitor after they click the emailed link: `/reset-password?token=...`
 * on a valid token, `/reset-password?error=INVALID_TOKEN` on an
 * expired/invalid one.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";

import { authClient } from "@intelligo-dev/auth/client";

import { Link } from "@/i18n/navigation";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Spinner } from "@/components/ui/spinner";
import {
  forgotPasswordSchema,
  type ForgotPasswordInput,
} from "@/lib/auth-validation";

export function ForgotPasswordForm() {
  const t = useTranslations("auth-password-reset");
  const [formError, setFormError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<ForgotPasswordInput>({
    resolver: zodResolver(forgotPasswordSchema),
  });

  async function onSubmit(data: ForgotPasswordInput) {
    try {
      setFormError(null);
      setIsLoading(true);

      const result = await authClient.requestPasswordReset({
        email: data.email,
        redirectTo: "/reset-password",
      });

      if (result.error) {
        setFormError(result.error.message ?? t("forgotForm.errors.unexpected"));
        setIsLoading(false);
        return;
      }

      setSuccess(true);
      setIsLoading(false);
    } catch (error) {
      console.error("Forgot password error:", error);
      setFormError(t("forgotForm.errors.unexpected"));
      setIsLoading(false);
    }
  }

  if (success) {
    return (
      <div className="space-y-4">
        <Alert>
          <AlertDescription>{t("forgotForm.successMessage")}</AlertDescription>
        </Alert>
        <Link href="/login" className="block">
          <Button type="button" variant="outline" className="w-full">
            {t("forgotForm.backToLogin")}
          </Button>
        </Link>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} noValidate className="space-y-4">
      {formError && (
        <Alert variant="destructive">
          <AlertDescription>{formError}</AlertDescription>
        </Alert>
      )}

      <div className="space-y-2">
        <Label htmlFor="email">{t("forgotForm.emailLabel")}</Label>
        <Input
          id="email"
          type="email"
          autoComplete="email"
          disabled={isLoading}
          aria-invalid={errors.email ? true : undefined}
          aria-describedby={errors.email ? "email-error" : undefined}
          {...register("email")}
        />
        {errors.email && (
          <p id="email-error" className="text-sm text-destructive">
            {t(`validation.${errors.email.message}`)}
          </p>
        )}
      </div>

      <Button type="submit" className="w-full" disabled={isLoading}>
        {isLoading ? (
          <span className="flex items-center justify-center gap-2">
            <Spinner />
            {t("forgotForm.submitting")}
          </span>
        ) : (
          t("forgotForm.submit")
        )}
      </Button>

      <p className="text-center text-sm text-muted-foreground">
        {t("forgotForm.rememberPassword")}{" "}
        <Link
          href="/login"
          className="font-medium text-primary hover:text-primary/80"
        >
          {t("forgotForm.logInLink")}
        </Link>
      </p>
    </form>
  );
}

"use client";

/**
 * Password reset completion form — reached by clicking the emailed
 * link. Better-Auth's own `/reset-password/:token` redirect appends
 * `?token=<value>` on a valid token or `?error=INVALID_TOKEN` /
 * `?error=TOKEN_EXPIRED` on an invalid/expired one, so both states are
 * read from search params rather than assumed. Calls the Better-Auth
 * client SDK's `resetPassword` action directly — no raw
 * `fetch("/api/auth/*")`.
 */

import { useState } from "react";
import { useSearchParams } from "next/navigation";
import { useTranslations } from "next-intl";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";

import { authClient } from "@intelligo-dev/auth/client";

import { useRouter } from "@/i18n/navigation";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Spinner } from "@/components/ui/spinner";
import {
  resetPasswordSchema,
  type ResetPasswordInput,
} from "@/lib/auth-validation";

export function ResetPasswordForm() {
  const t = useTranslations("auth-password-reset");
  const router = useRouter();
  const searchParams = useSearchParams();
  const token = searchParams.get("token");
  const linkError = searchParams.get("error");

  const [formError, setFormError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<ResetPasswordInput>({
    resolver: zodResolver(resetPasswordSchema),
  });

  async function onSubmit(data: ResetPasswordInput) {
    if (!token) {
      setFormError(t("resetForm.errors.invalidLink"));
      return;
    }

    try {
      setFormError(null);
      setIsLoading(true);

      const result = await authClient.resetPassword({
        newPassword: data.password,
        token,
      });

      if (result.error) {
        setFormError(result.error.message ?? t("resetForm.errors.invalidLink"));
        setIsLoading(false);
        return;
      }

      router.push("/login?reset=success");
    } catch (error) {
      console.error("Reset password error:", error);
      setFormError(t("resetForm.errors.invalidLink"));
      setIsLoading(false);
    }
  }

  if (!token || linkError) {
    return (
      <Alert variant="destructive">
        <AlertDescription>
          {t("resetForm.errors.invalidLinkFromForgotPage")}
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} noValidate className="space-y-4">
      {formError && (
        <Alert variant="destructive">
          <AlertDescription>{formError}</AlertDescription>
        </Alert>
      )}

      <div className="space-y-2">
        <Label htmlFor="password">{t("resetForm.passwordLabel")}</Label>
        <Input
          id="password"
          type="password"
          autoComplete="new-password"
          disabled={isLoading}
          aria-invalid={errors.password ? true : undefined}
          aria-describedby={errors.password ? "password-error" : undefined}
          {...register("password")}
        />
        {errors.password && (
          <p id="password-error" className="text-sm text-destructive">
            {t(`validation.${errors.password.message}`)}
          </p>
        )}
      </div>

      <div className="space-y-2">
        <Label htmlFor="confirmPassword">
          {t("resetForm.confirmPasswordLabel")}
        </Label>
        <Input
          id="confirmPassword"
          type="password"
          autoComplete="new-password"
          disabled={isLoading}
          aria-invalid={errors.confirmPassword ? true : undefined}
          aria-describedby={
            errors.confirmPassword ? "confirm-password-error" : undefined
          }
          {...register("confirmPassword")}
        />
        {errors.confirmPassword && (
          <p id="confirm-password-error" className="text-sm text-destructive">
            {t(`validation.${errors.confirmPassword.message}`)}
          </p>
        )}
      </div>

      <Button type="submit" className="w-full" disabled={isLoading}>
        {isLoading ? (
          <span className="flex items-center justify-center gap-2">
            <Spinner />
            {t("resetForm.submitting")}
          </span>
        ) : (
          t("resetForm.submit")
        )}
      </Button>
    </form>
  );
}

